function extend_official_modes()
%EXTEND_OFFICIAL_MODES Algorithms remain embedded in individual model Charts.
root=stampfly_project_root();init_official;
m='StampFly_Official_Bench400';open_system(stampfly_model_file(m));
lm=layout.LayoutStateManager.instance();lm.reset();
% Add only the extra physical inputs; state management receives packet events.
x=edit(m,'blk_38',{add('Inport','FlipButton','button',struct('Port','11')), ...
 add('Chart','OfficialFlightSupervisor','supervisor',struct),add('Chart','OfficialFlipSequence','flip',struct), ...
 add('UnitDelay','ControlResetMemory','reset',struct('SampleTime','Official.Step','InitialCondition','false')), ...
 add('UnitDelay','RateReferenceMemory','rate',struct('SampleTime','Official.Step','InitialCondition','zeros(3,1,''single'')')), ...
 add('UnitDelay','FlipFlagMemory','flag',struct('SampleTime','Official.Step','InitialCondition','uint8(0)')), ...
 add('Logic','ResetAHRS','ahrs',struct('Operator','OR','Inputs','2')), ...
 add('Outport','AltFlag','altOut',struct('Port','13')),add('Outport','LinkConnected','linkOut',struct('Port','14')),add('Outport','FlipFlag','flipOut',struct('Port','15'))});
populate(m,x.supervisor,{'previousMode','uint8';'button','uint8';'newPacket','uint8';'flags','uint8';'ahrsFlag','uint8'}, ...
 {'branch','uint8';'mode','uint8';'ahrsReset','boolean';'parkingReset','boolean';'connected','uint8'},fullfile(root,'code','model_algorithms','FlightSupervisor.m'));
populate(m,x.flip,{'button','uint8';'branch','uint8';'voltage','single';'previousReset','boolean';'lastRate','single'}, ...
 {'start','boolean';'done','boolean';'phase','uint8';'thrust','single';'rollRate','single';'angleReset','boolean';'ahrsReset','boolean';'normalControl','boolean'},fullfile(root,'code','model_algorithms','FlipSequence.m'));
% Add control interface ports without hiding any of the existing seven PIDs.
names={'PreMode','FlipPhase','FlipThrust','FlipRate','FlipStart','FlipDone','FlipAngleReset'};ops={};
for k=1:numel(names),ops{end+1}=add('Inport',names{k},['i' num2str(k)],struct('Port',num2str(k+10)));end
outNames={'AltFlag','FlipFlag','Reset','RateReference','FinalMode'};
for k=1:numel(outNames),ops{end+1}=add('Outport',outNames{k},['o' num2str(k)],struct('Port',num2str(k+3)));end
ops=[ops,{add('UnitDelay','LastRateReference','lastRate',struct('SampleTime','Official.Step','InitialCondition','zeros(3,1,''single'')')), ...
 add('Logic','ResetAngles','angleReset',struct('Operator','OR','Inputs','3')), ...
 add('Chart','FinalizeFlightMode','final',struct)}];
c=edit(m,'blk_92',ops);
update(m,126,{'phase','uint8';'flipDone','boolean'},{'controlMode','single'},fullfile(root,'code','model_algorithms','TakeoffLandingCommand.m'), ...
 {'stick','height','voltage','rangeFlag','mode','phase','flipDone'},{'alt','base','counter','raw','auto','manual','controlMode'});
update(m,127,{'phase','uint8';'flipThrust','single';'flipStart','boolean';'flipDone','boolean';'finalMode','uint8'},{'angleReset','boolean';'flipFlag','uint8'},fullfile(root,'code','model_algorithms','ControlEnableReset.m'), ...
 {'raw','manual','auto','mode','controlMode','dt','oldFilter','lastThrust','phase','flipThrust','flipStart','flipDone','finalMode'}, ...
 {'command','run','reset','altEnable','angleEnable','velEnable','angleReset','flipFlag'});
update(m,128,{'phase','uint8';'flipRate','single';'angleReset','boolean';'lastRate','single';'flipDone','boolean';'controlMode','single'},{},fullfile(root,'code','model_algorithms','StickToAngleRate.m'), ...
 {'stick','mode','run','reset','phase','flipRate','angleReset','lastRate','flipDone','controlMode'},{'angle','directRate','resetError'});
update(m,130,{'auto','boolean';'flipFlag','uint8'},{},fullfile(root,'code','model_algorithms','VerticalReference.m'),{'zRef','mode','auto','flipFlag'},{'vRef'});
update(m,131,{'flipFlag','uint8'},{},fullfile(root,'code','model_algorithms','ThrustCorrectionLimits.m'), ...
 {'command','correction','base','auto','manual','velEnable','mode','dt','oldFilter','lastThrust','flipFlag'},{'thrust','filter','last'});
populate(m,c.final,{'branch','uint8';'preMode','uint8';'height','single';'flipStart','boolean';'flipDone','boolean';'overG','uint8'},{'mode','uint8'},fullfile(root,'code','model_algorithms','FinalizeMode.m'));
ops={wire([c.i2 '.y1'],'blk_126.u6'),wire([c.i6 '.y1'],'blk_126.u7'), ...
 wire([c.i2 '.y1'],'blk_127.u9'),wire([c.i3 '.y1'],'blk_127.u10'),wire([c.i5 '.y1'],'blk_127.u11'),wire([c.i6 '.y1'],'blk_127.u12'),wire([c.final '.y1'],'blk_127.u13'),wire('blk_126.y7','blk_127.u5'), ...
 wire([c.i2 '.y1'],'blk_128.u5'),wire([c.i4 '.y1'],'blk_128.u6'),wire('blk_127.y7','blk_128.u7'),wire([c.lastRate '.y1'],'blk_128.u8'),wire([c.i6 '.y1'],'blk_128.u9'),wire('blk_126.y7','blk_128.u10'), ...
 wire('blk_129.y1',[c.lastRate '.u1']),wire('blk_129.y1',[c.o4 '.u1']), ...
 wire('blk_126.y5','blk_130.u3'),wire('blk_127.y8','blk_130.u4'),wire([c.final '.y1'],'blk_130.u2'),wire('blk_127.y8','blk_131.u11'), ...
 wire('blk_103.y1',[c.final '.u1']),wire([c.i1 '.y1'],[c.final '.u2']),wire('blk_98.y1',[c.final '.u3']),wire([c.i5 '.y1'],[c.final '.u4']),wire([c.i6 '.y1'],[c.final '.u5']),wire('blk_102.y1',[c.final '.u6']), ...
 wire([c.final '.y1'],[c.o5 '.u1']),wire('blk_126.y5',[c.o1 '.u1']),wire('blk_127.y8',[c.o2 '.u1']), ...
 wire('blk_127.y3',[c.o3 '.u1']),wire('blk_127.y3',[c.angleReset '.u1']),wire('blk_127.y7',[c.angleReset '.u2']),wire([c.i7 '.y1'],[c.angleReset '.u3']), ...
 wire([c.angleReset '.y1'],'blk_239.u4'),wire([c.angleReset '.y1'],'blk_284.u4')};
% Terminate unused StickFields outputs and estimated Yaw (no absolute heading PID).
for k=[1 2 3 4 6],ops=[ops,{add('Terminator',['UnusedStick' num2str(k)],['t' num2str(k)],struct),wire(['blk_135.y' num2str(k)],['#t' num2str(k) '.u1'])}];end
ops=[ops,{add('Terminator','UnusedYaw','tyaw',struct),wire('blk_137.y3','#tyaw.u1'),add('Terminator','UnusedStickMode','tmode',struct),wire('blk_135.y5','#tmode.u1')}];
edit(m,'blk_92',ops);model_check(m,'blk_92','["all"]');
% Sensor flags use altitude and the preceding flip phase, as sensor_read runs first.
sensor=edit(m,'blk_72',{add('Inport','FlipFlag','flip',struct('Port','11'))});
rt=sfroot;p=Simulink.ID.getFullName([m ':124']);ch=rt.find('-isa','Stateflow.Chart','Path',p);fn=ch.find('-isa','Stateflow.EMFunction');script=fn.Script;
script=strrep(script,'velocity','height');script=strrep(script,'dt,parkingReset)','dt,parkingReset,flipFlag)');
script=strrep(script,'altFlag~=0)','altFlag~=0 && flipFlag==0)');
file=fullfile(root,'code','model_algorithms','SensorFlags.m');fid=fopen(file,'w','n','UTF-8');fprintf(fid,'%s',script);fclose(fid);
update(m,124,{'flipFlag','uint8'},{},file,{'accel','azd','voltage','mode','altFlag','height','rawRange','dt','parkingReset','flipFlag'},{'flags'});
edit(m,'blk_124',{struct('op','configure','target','sf_124:6','params',struct('Name','height'))});
edit(m,'blk_72',{wire([sensor.flip '.y1'],'blk_124.u10'),wire('blk_123.y1','blk_124.u6')});model_check(m,'blk_72','["all"]');
s=x.supervisor;f=x.flip;
ops={struct('op','delete','target','blk_64'),wire('blk_66.y1',[s '.u1']),wire('blk_47.y1',[s '.u2']),wire('blk_48.y1',[s '.u3']),wire('blk_72.y5',[s '.u4']),wire('blk_49.y1',[s '.u5']), ...
 wire([s '.y1'],'blk_92.u9'),wire([s '.y2'],'blk_92.u11'),wire([s '.y4'],'blk_68.u1'),wire([s '.y5'],[x.linkOut '.u1']), ...
 wire([x.button '.y1'],[f '.u1']),wire([s '.y1'],[f '.u2']),wire('blk_45.y1',[f '.u3']),wire([x.reset '.y1'],[f '.u4']),wire([x.rate '.y1'],[f '.u5']), ...
 wire([f '.y3'],'blk_92.u12'),wire([f '.y4'],'blk_92.u13'),wire([f '.y5'],'blk_92.u14'),wire([f '.y1'],'blk_92.u15'),wire([f '.y2'],'blk_92.u16'),wire([f '.y6'],'blk_92.u17'), ...
 wire('blk_92.y4','blk_69.u1'),wire('blk_92.y4',[x.altOut '.u1']),wire('blk_92.y5',[x.flag '.u1']),wire('blk_92.y5',[x.flipOut '.u1']),wire([x.flag '.y1'],'blk_72.u11'), ...
 wire('blk_92.y6',[x.reset '.u1']),wire('blk_92.y7',[x.rate '.u1']),wire('blk_92.y8','blk_66.u1'),wire('blk_92.y8','blk_53.u1'), ...
 wire([s '.y3'],[x.ahrs '.u1']),wire([f '.y7'],[x.ahrs '.u2']),wire([x.ahrs '.y1'],'blk_67.u1'), ...
 add('Terminator','FlipNormalDiagnostic','tnormal',struct),wire([f '.y8'],'#tnormal.u1')};
edit(m,'blk_38',ops);model_check(m,'blk_38','["all"]');
edit(m,'root',{struct('op','configure','target','blk_9','params',struct('System','official.Joystick400'))});
ops={wire('blk_9.y5','blk_38.u11'),wire('blk_9.y6','blk_38.u8'),wire('blk_38.y14','blk_32.u1'), ...
 add('Terminator','RawLinkAgeUnused','tlink',struct),wire('blk_9.y3','#tlink.u1'), ...
 add('Terminator','PacketErrorDiagnostic','terr',struct),wire('blk_9.y7','#terr.u1'), ...
 add('Terminator','AltFlagDiagnostic','talt',struct),wire('blk_38.y13','#talt.u1'),add('Terminator','FlipFlagDiagnostic','tflip',struct),wire('blk_38.y15','#tflip.u1')};
edit(m,'root',ops);model_check(m,'root','["all"]');save_system(m);
save(fullfile(root,'tests','modular_mode_ids.mat'),'x','c','sensor');
end
function populate(m,id,ins,outs,file)
ops={struct('op','configure','target',['chart:' m],'params',struct('ActionLanguage','MATLAB'))};
for k=1:size(ins,1),ops{end+1}=add('Data',ins{k,1},['i' num2str(k)],struct('Scope','Input','DataType',ins{k,2}));end
for k=1:size(outs,1),ops{end+1}=add('Data',outs{k,1},['o' num2str(k)],struct('Scope','Output','DataType',outs{k,2}));end
script=rename(fileread(file),[ins(:,1);outs(:,1)]);
label=['Calculate' newline 'en,du: [' strjoin(outs(:,1),',') ']=stepFn(' strjoin(ins(:,1),',') ');'];
ops=[ops,{struct('op','add_block','type','EMFunction','ref','fn','params',struct('Script',script)),add('State','Calculate','run',struct('LabelString',label)),struct('op','connect','target','? -> #run')}];
edit(m,id,ops);model_check(m,id,'["stateflow_lint"]');
end
function update(m,sid,newIns,newOuts,file,ins,outs)
id=['blk_' num2str(sid)];r=char(model_read(m,id,'0'));fn=regexp(r,'MLFunction:.*?- id: "([^"]+)"','tokens','once');st=regexp(r,'State:.*?- id: "([^"]+)"','tokens','once');
ops={};for k=1:size(newIns,1),ops{end+1}=add('Data',newIns{k,1},['i' num2str(k)],struct('Scope','Input','DataType',newIns{k,2}));end
for k=1:size(newOuts,1),ops{end+1}=add('Data',newOuts{k,1},['o' num2str(k)],struct('Scope','Output','DataType',newOuts{k,2}));end
script=rename(fileread(file),[ins(:);outs(:)]);
ops=[ops,{struct('op','configure','target',fn{1},'params',struct('Script',script)),struct('op','configure','target',st{1},'params',struct('LabelString',['Calculate' newline 'en,du: [' strjoin(outs,',') ']=stepFn(' strjoin(ins,',') ');']))}];
edit(m,id,ops);model_check(m,id,'["stateflow_lint"]');
end
function script=rename(script,names)
for k=1:numel(names),script=regexprep(script,['\<' names{k} '\>'],['arg_' names{k}]);end
end
function ids=edit(m,scope,ops)
model_read(m,scope,'0');r=char(model_edit(m,scope,jsonencode(ops),'incremental'));
if ~startsWith(strtrim(r),'status: ok'),model_read(m,scope,'0');model_check(m,scope,'["all"]');error('official:EditFailed','%s',r);end
t=regexp(r,'(?m)^\s+(\w+): (blk_\d+)\s*$','tokens');ids=struct;for k=1:numel(t),ids.(t{k}{1})=t{k}{2};end
end
function op=add(type,name,ref,params),op=struct('op','add_block','type',type,'name',name,'ref',ref,'params',params);end
function op=wire(a,b),op=struct('op','connect','target',[a ' -> ' b]);end
